// Maple Bay City Hall (showpiece S8) — gameplay for the converted `bld.downtown.cityhall` on City Hall Plaza (the building, the plaza and every world file are untouched).
// Rooms: scenes/rooms/cityhall.js (rotunda `cityhall` + fixture handlers), cityhall_council.js (`cityhall_council`), cityhall_records.js (`cityhall_records`, `cityhall_archive`),
//   cityhall_upper.js (`cityhall_clerk` with the wedding room, `cityhall_mayor`, `cityhall_tower`), cityhall_views.js (rendered pictures). Data: data/cityhall.js. Art: art/showpiece/cityhall*.js, _ch_lib.js, _ch_icons.js.
//
// City (once per city world, order 56.5 = after showpieces, before lobbies / places / stalls / addresses), all runtime, nothing saved in the world:
//   door poi `door:cityhall` (room `cityhall`, the doorstep the interim "Town Hall" lobby `lobby:4` used: G.places.get('lobby:4') / 'door:lobby:4' still resolve to City Hall, an old save made inside
//   `int:lobby:4` loads into the rotunda, flags.lastDoor is migrated); prop `prop.cityhall.fountain` drawn over the plaza fountain (dry + tarpaulin + "FIXED SOON" until the chain is done, then
//   running, animated); bunting on the portico after the bunting ballot; four protesters with placards on council days 16:00 - 20:30; Marta the plumber at her pitch (poi `ch_plumber`); a busking spot and
//   a stall spot on the plaza (permits); the ceremony crowd + ribbon; people sitting on the fountain rim once it runs.
// Hours: Mon - Fri 08:30 - 17:00 (Tue + Thu until 21:00 for council), Sat 10:00 - 16:00 (weddings), Sun + holidays closed. Records windows Mon - Fri 09:00 - 16:30; archive Mon - Fri 10 - 16, Sat 10 - 14;
//   clock tower lunchtimes 12 - 14, Saturdays and during the public tour.
// G.cityhall = {
//   isOpen(), hours() -> [open, close] | null, enter() (city door), arrived / arrivedIn (room hooks), look() -> { bunting, buntingC, flowers, statue, fixed, hero, ballotOpen } (what the ballots + chain changed),
//   fountainFixed() -> bool   (also G.state.flags.fountain_fixed; event 'cityhall:fountain')
//   lookUp() (dome view), model(fx, scene, i?) (light a district), portrait(k), info(char?), directory(), guard(char?), notices(), statue(), shop(), sit(fx, scene), plaque(),
//   queue: { state() -> { serving, win, ticket, ahead, mine, called }, take() -> ticket | null, canServe() }, takeNumber(scene), wait(fx, scene), window(n, scene), forms(), photo(fx, scene),
//   bills: { view() -> money bills, payArrears() -> bool, dispute(i?) -> 'won' | 'lost' | null }, id: { has(), card() (show it), issue() -> bool }, licence kinds: buyLicence('dog' | 'bike'), buyPermit('busk' | 'stall'),
//   hasPermit(k) -> bool, records(homeId?) -> text | menu, lostFound(),
//   council: { state() -> { on, i, m, phase, motion, res, shown, you } , next() -> { day, from, to }, agenda(day?) -> [motions], signup(id?) -> bool, speak(tone?) -> Promise<bool>, watch(fx?, scene?), minutes(), force({ m } | null) },
//   signup(scene, char?), podium(fx, scene), board(scene),
//   ballot: { now() -> { id, q, opts, voted, open }, open() (menu), vote(optId) -> bool, count() (close this week's ballot now), results() },
//   wedding: { next() -> { day, hour }, slots(day) -> [hours], isOn(), fee, book(partnerId, day?, slot?) -> { day, slot } | null, booked(), cancel(), mine() -> { partner, spec } | null, confetti() -> bool,
//              kiss(scene) / over(scene) (room hooks) },                       // defensive hook for a future romance system; emits 'cityhall:married'(partnerId)
//   clerk(scene, char?), licence(scene, char?), registrar(scene), secretary(scene, char?), toMayor(), mayorIn(), mayorBusy(), mayorSpec(), talkMayor(char, where), mayorDesk(scene), mayorChair(fx, scene), keycase(), balcony(),
//   toArchive(), archivist(scene, char?), shelves(fx), mapcase(fx, scene), microfilm(fx, scene), reel: { state(), go(i), step(d), read() }, reading(), photos(k), news(),
//   toTower(), wind(fx, scene), bell(scene), scope(), view(k), talkKeeper(char), struck(hour, scene), tour() -> Promise,
//   chain() -> { st 0..8, drawer, cer }, chainStart(), plumber() -> { x, y } | null, talkPlumber(), fountain() (the city interactable), ceremony(force?) -> Promise, ceremonyReady(),
//   busk() / stall() (plaza, with permits), confetti(x, y, n), stats(), debug: { stay (no closing walk-out), setChain(st) } }
// Chain "The Fountain" (goal `ch_fountain`): 1 ask at window 4 -> 2 archive (microfilm June 1962 -> drawer 62-F: blueprint + work order) -> 3 clerk, then speak for it at a council meeting so the
//   vote carries -> 4 find Marta the plumber -> 5 the valve key is in Lost & Found (needs a Resident Card) -> 6 bring Marta the key -> 7 ceremony on the plaza next day 10:00 - 18:00 -> 8 done.
// State: G.state.cityhall = { visits, lastDay, photo, id: { no, day } | null, lic: { dog, bike }, permits: { busk, stall }, q: { k, day, served }, form, dispute, council: { watched, spoke, sign, fix, boost: {..}, voted },
//   ballot: { week, pick, done }, look: { bunting, flowers, statue }, results: [..], wed: { seen, witness, booked }, arch: { read: { year: 1 }, maps: {}, pos }, tower: { winds, windDay, bells, viewDay }, lostDay,
//   appt: { t } | null, chain: { st, drawer, cer, clerk }, fixedDay, hero, model: n, dome, portraits: {..}, tourDay, busk: { day, n }, stallDay, coinDay }.  Flags: fountain_fixed, cityhall_friend.
// Events: 'cityhall:visit'(first), ':number'(ticket), ':served'(windowId), ':id', ':permit'(kind), ':licence'(kind), ':bill'(kind), ':record'(homeId), ':watch', ':speak'(motionId), ':vote'(ballotId, opt),
//   ':ballot'(ballotId, winner), ':wedding', ':married'(partnerId), ':reel'(year), ':wind', ':bell'(hour), ':chain'(st), ':fountain' (it runs), ':tour', ':busk'(tips), ':stall'(sold).
// Guide stamps: x:ch_visit, x:ch_dome, x:ch_id, x:ch_council, x:ch_speak, x:ch_wedding, x:ch_reel, x:ch_clock, x:ch_fountain.
// Tuning: data/cityhall.js TUNE (QUEUE_MIN 5 game minutes per number, WATCH_MIN 20, SPEAK_MIN 6, WIND_MIN 6, BUSK_MIN 30, STALL_MIN 60, FUND 340, REWARD 150, WALKOUT 20), FEES, COUNCIL, WEDDING, TOUR.
