function confetti(x, y, n = 14, z = 2.4) { const sid = G.scene && G.scene.id; for (let i = 0; i < n && parts.length < 420; i++) parts.push({ s: sid, x: x + (Math.random() - .5) * 1.2, y: y + (Math.random() - .5) * 1.2, z: z + Math.random() * 1.2, vx: (Math.random() - .5) * 1.4, vy: (Math.random() - .5) * 1.4, vz: .6 + Math.random() * 1.2, c: CCOL[Math.floor(Math.random() * CCOL.length)], t: 2.2 + Math.random() * 1.6, g: G.scene && G.scene.world ? G.scene.world.heightAt(Math.max(1, x), Math.max(1, y)) : 0 }); }
