/* ---------- the clock tower ---------- */
function toTower() { const n = G.now(); if (!towerOpen(n) && !friend() && !debug.stay && !tourRun) { toast('A rope across the stair: "CLOCK TOWER. Open lunchtimes 12 to 14 and all day Saturday. 112 steps."', 'info', 4200); return false; } goRoom('tower', 'door'); return true; }
function wind(fx, sc) { const S = st(), n = G.now(); if (G.busy) return false; if (S.tower.windDay === n.day) { toast('Wound for today. The big wheel turns one tooth every two seconds, and has since 1911.', 'info', 4000); return false; }
  G.startActivity({ label: 'Winding the clock', anim: 'work', minutes: TUNE.WIND_MIN, rate: 1, done: () => { S.tower.windDay = n.day; S.tower.winds = (S.tower.winds || 0) + 1; xp('fitness', 3); xp('handiness', 3); add('fun', 5); stamp('x:ch_clock'); G.emit('cityhall:wind'); const k = sc && sc.hot && sc.hot.keeper; if (k && !k.hidden) bubble(k, pick(['Forty turns. You have got the arms for it.', 'There. Maple Bay has tomorrow, thanks to you.', 'Steady... steady... THAT is a wound clock.']), 4200); toast('Forty turns of an iron crank the size of a bicycle. The weights rise; the whole city has its time for another day.', 'good', 5000); } }); return true; }
function bell(sc) { const n = G.now(); if ((n.hf % 1) < .12 && sc && sc.hot) { sc.hot.ring(); return; } toast(`A bronze bell as tall as you, cast 1911: "I MARK THE HOURS OF A FREE CITY". It rings on the hour; next at ${clock(Math.floor(n.hf) + 1)}.`, 'info', 4600); }
function struck(hr, sc) { const S = st(); if (G.scene !== sc) return; S.tower.bells = (S.tower.bells || 0) + 1; add('fun', 4); G.emit('cityhall:bell', hr); toast(hr === 12 ? 'NOON. Twelve strokes, from inside the bell. You will hear them in your teeth until Thursday.' : `${hr % 12 || 12} o'clock. The floor hums. A pigeon outside reconsiders its life.`, 'good', 4600); }
